import java.util.*;
class Solution { public int[] minInterval(int[][]in,int[]q){Arrays.sort(in,(a,b)->a[0]-b[0]);int[][]x=new int[q.length][2];for(int i=0;i<q.length;i++){x[i][0]=q[i];x[i][1]=i;}Arrays.sort(x,(a,b)->a[0]-b[0]);PriorityQueue<int[]>h=new PriorityQueue<>((a,b)->a[0]-b[0]);int[]r=new int[q.length];int j=0;for(int[]v:x){while(j<in.length&&in[j][0]<=v[0]){h.offer(new int[]{in[j][1]-in[j][0]+1,in[j][1]});j++;}while(!h.isEmpty()&&h.peek()[1]<v[0])h.poll();r[v[1]]=h.isEmpty()?-1:h.peek()[0];}return r;} }
